#endif /* ASW_CODEC_H：结束头文件保护，不是结束一个运行中的if。 */

/* codec.c：唯一实现。只处理信号与字节，不读取用户输入、不打印界面。 */
#include "codec.h" /* 引号表示本项目头文件；本文件也需核对接口声明。 */
#include <math.h>  /* isfinite与roundf；GCC链接时需要数学库m。 */

int Codec_Encode(float speed, int mode, int radar, uint8_t *data, size_t length) {
    /* [编码校验] 先检查接口，再检查业务范围，全部通过才写data。
     * DBC描述范围，不会让C自动插入这些if。||任一错误成立就拒绝。 */
    if (data == NULL || length != 8) return CODEC_INTERFACE;
    if (!isfinite(speed) || speed < 0.0f || speed > 250.0f
        || mode < 0 || mode > 2 || radar < 0 || radar > 1) return CODEC_INVALID;

    /* [编码写入] 自定义教学车速协议：0.1km/h一刻度、16位无符号、小端。
     * 72.5×10=725=0x02D5。先清8格，再写低字节D5、高字节02和控制05。 */
    uint32_t raw = (uint32_t)roundf(speed * 10.0f);
    for (size_t i = 0; i < 8; i++) data[i] = 0;
    data[0] = (uint8_t)(raw & 255u);
    data[1] = (uint8_t)((raw >> 8) & 255u);
    data[2] = (uint8_t)((uint32_t)mode | ((uint32_t)radar << 2));
