#ifndef ASW_ACC_STATE_H
#define ASW_ACC_STATE_H

/* 只定义类型与函数接口，不在头文件中执行状态机。 */
typedef enum {
    ACC_OFF = 0,
    ACC_READY = 1,
    ACC_ACTIVE = 2,
    ACC_FAULT = 3
} AccState;

typedef struct {
    int driver_enable;   /* 驾驶员使能：0或1 */
    int radar_valid;     /* 雷达数据有效：0或1 */
    int fault_present;   /* 故障标志：0或1 */
    int fault_reset;     /* 请求复位故障：0或1 */
    float distance_m;    /* 前方距离，单位m */
} AccInput;

typedef struct {
    float alert_enter_m; /* 距离<=此值，进入距离偏小提示 */
    float alert_exit_m;  /* 距离>=此值，退出提示；必须比进入值大 */
} AccCalibration;

typedef struct {
    AccState state;      /* 本轮前的状态会保留到下一轮 */
    int spacing_alert;  /* 0关闭、1提示 */
} AccContext;

typedef struct {
    AccState state;      /* 本轮计算的状态 */
    int spacing_alert;  /* 本轮是否有距离偏小提示 */
    int valid;          /* 本轮输出是否有效 */
} AccOutput;

/* 声明：上下文地址、输入地址、标定地址、输出地址；返回0/-1/-2。 */
int Acc_Step(AccContext *context, const AccInput *input,
             const AccCalibration *calibration, AccOutput *output);

#endif

#include "acc_state.h"
#include <stddef.h>
#include <math.h>

/* 一个调用只处理一帧；本文件没有main，也不连接真实车辆。 */
int Acc_Step(AccContext *context, const AccInput *input,
             const AccCalibration *calibration, AccOutput *output)
{
    /* 输出对象必须存在；先清成无效，防止旧值被误用。 */
    if (output == NULL) return -1;
    *output = (AccOutput){.state = ACC_FAULT, .valid = 0};

    if (context == NULL || input == NULL || calibration == NULL) return -1;
    if (!isfinite(input->distance_m) || input->distance_m < 0.0f ||
        input->distance_m > 500.0f) return -2;
    if (!isfinite(calibration->alert_enter_m) ||
        !isfinite(calibration->alert_exit_m) ||
        calibration->alert_enter_m < 0.0f ||
        calibration->alert_enter_m >= calibration->alert_exit_m ||
        calibration->alert_exit_m > 500.0f) return -2;
    if ((input->driver_enable != 0 && input->driver_enable != 1) ||
        (input->radar_valid != 0 && input->radar_valid != 1) ||
        (input->fault_present != 0 && input->fault_present != 1) ||
        (input->fault_reset != 0 && input->fault_reset != 1)) return -2;
    if (context->state < ACC_OFF || context->state > ACC_FAULT ||
        (context->spacing_alert != 0 && context->spacing_alert != 1)) return -2;

    /* 先复制旧状态；本次成功后才写回调用者的context。 */
    AccContext next = *context;

    /* 故障优先；已进入故障后，需要故障清除+关闭使能+请求复位。 */
    if (input->fault_present != 0) {
        next.state = ACC_FAULT;
    } else if (next.state == ACC_FAULT) {
        if (input->fault_reset != 0 && input->driver_enable == 0) {
            next.state = ACC_OFF;
        }
    } else if (input->driver_enable == 0) {
        next.state = ACC_OFF;
    } else if (input->radar_valid == 0) {
        next.state = ACC_READY;
    } else {
        next.state = ACC_ACTIVE;
    }

    /* 滞环仅在ACTIVE中生效；非ACTIVE重置提示。 */
    if (next.state != ACC_ACTIVE) {
        next.spacing_alert = 0;
    } else if (next.spacing_alert == 0 &&
               input->distance_m <= calibration->alert_enter_m) {
        next.spacing_alert = 1;
    } else if (next.spacing_alert == 1 &&
               input->distance_m >= calibration->alert_exit_m) {
        next.spacing_alert = 0;
    }

    /* 写回：context保存跨帧状态；output只表示当前这一帧。 */
    *context = next;
    output->state = next.state;
    output->spacing_alert = next.spacing_alert;
    output->valid = 1;
    return 0;
}

#include "acc_state.h"
