        out.state != ACC_ACTIVE || out.spacing_alert != 0) return 1;
    in.distance_m = 34.0f;
    if (Acc_Step(&ctx, &in, &cfg, &out) != 0 || out.spacing_alert != 1) return 2;
    in.distance_m = 40.0f;
    if (Acc_Step(&ctx, &in, &cfg, &out) != 0 || out.spacing_alert != 1) return 3;
    in.distance_m = 42.0f;
    if (Acc_Step(&ctx, &in, &cfg, &out) != 0 || out.spacing_alert != 0) return 4;

    in.fault_present = 1;
    if (Acc_Step(&ctx, &in, &cfg, &out) != 0 || out.state != ACC_FAULT) return 5;
    in.fault_present = 0;
    if (Acc_Step(&ctx, &in, &cfg, &out) != 0 || out.state != ACC_FAULT) return 6;
    in.driver_enable = 0;
