#ifndef VEHICLE_IF_H
#define VEHICLE_IF_H
#include <stdint.h> /* uint32_t用于周期号和毫秒时间戳。 */

/* 【输入类型】typedef给结构体类型起名；此处还没有创建sample对象。 */
typedef struct {
    float speed_kmh;       /* 车速，单位km/h，必须是有限数且在0～250之间。 */
    float distance_m;      /* 前车距离，单位m，必须是有限数且在0～500之间。 */
    int radar_valid;       /* 1：雷达数据有效；0：不可用。 */
    uint32_t cycle;        /* 采样轮次，供记录数据来源。 */
    uint32_t now_ms;       /* 本次应用检查时刻，单位ms；模拟数据给定。 */
    uint32_t stamp_ms;     /* 传感器采样时刻，单位ms；不处理计数器回绕。 */
    int driver_enable;     /* 1：驾驶员启用；0：未启用。 */
    int fault_present;     /* 1：传感器报告故障；0：未报告。 */
} VehicleSample;

/* 【故障枚举】一个明确的编号对应一个故障原因；不是硬件诊断DTC。 */
typedef enum {
    FAULT_NONE = 0,        /* 数据有效，无故障。 */
    FAULT_READ = 1,        /* VehicleIf_Read失败。 */
    FAULT_SENSOR = 2,      /* 雷达有效标志不正确。 */
    FAULT_RANGE = 3,       /* 速度或距离为NaN/inf/超范围。 */
    FAULT_TIMEOUT = 4,     /* 时间戳超前，或数据年龄大于100ms。 */
    FAULT_DISABLED = 5,    /* 驾驶员未启用，不能发布有效判断。 */
    FAULT_DEVICE = 6       /* 传感器上报故障。 */
} FaultCode;

/* 【输出类型】valid=0时warning=0只是占位，不表示前车距离安全。 */
typedef struct {
    int warning;           /* 1：距离<=35m；0：未触发，只有valid=1才有意义。 */
    int valid;             /* 1：本次提示结果有效；0：不可用于决策。 */
    uint32_t cycle;        /* 与输入采样轮次对应；Read失败时保持0。 */
    FaultCode fault_code;  /* 本轮故障原因；Write失败时本轮结果根本未发布。 */
} VehicleResult;

/* 【接口声明】实现写在mock.c；app.c只调用这两个接口。 */
int VehicleIf_Read(VehicleSample *out);              /* out指向应用的可写sample。 */
int VehicleIf_Write(const VehicleResult *result);    /* result指向只读输出。 */
#endif

#ifndef APP_H
#define APP_H
/* 【应用入口】由demo.c每帧调用一次，输入来自VehicleIf_Read接口。 */
/* 返回0成功；-2读取失败；-3输入不可用；-4写接口失败。 */
/* 返回码、输出valid、是否真的published是三件不同的事。 */
int App_RunOnce(void);
#endif

#include "app.h"       /* App_RunOnce函数声明。 */
#include "vehicle_if.h" /* 输入/输出结构体、FaultCode和接口函数原型。 */
#include <math.h>      /* isfinite：必须显式排除NaN与无穷大。 */

/* 【业务函数】mock可替换为别的接口实现，app不访问STEPS数组。 */
int App_RunOnce(void)
{
    /* 【1 创建对象】这是有名字的局部对象，每次调用重新初始化。 */
    VehicleSample sample = {0}; /* sample本身是结构体，访问成员用点号。 */
    VehicleResult result = {0}; /* valid=0、warning=0、fault_code=0。 */

    /* 【2 读输入】&sample取对象地址；mock.c的*out会覆盖整个sample。 */
    int read_status = VehicleIf_Read(&sample);
    if (read_status != 0) {
        result.fault_code = FAULT_READ;
        /* 即使Read失败，也尝试写出一份明确标为无效的结果。 */
        if (VehicleIf_Write(&result) != 0) return -4;
        return -2;
    }

    /* 【3 关联周期】只有Read成功后，sample.cycle才来自本轮输入。 */
    result.cycle = sample.cycle;

    /* 【4 需求R03：有限性和范围】NaN与任何大小比较通常都为假。 */
    /* 因此只写speed<0或speed>250不能拒绝NaN，必须先用isfinite。 */
    if (!isfinite(sample.speed_kmh) || !isfinite(sample.distance_m) ||
        sample.speed_kmh < 0.0f || sample.speed_kmh > 250.0f ||
        sample.distance_m < 0.0f || sample.distance_m > 500.0f) {
        result.fault_code = FAULT_RANGE;
    }
    /* 【需求R04：数据新鲜度】先检查未来时间，再进行无符号减法。 */
    else if (sample.stamp_ms > sample.now_ms ||
             sample.now_ms - sample.stamp_ms > 100U) {
        result.fault_code = FAULT_TIMEOUT;
    }
    /* 【需求R03：传感器状态、使能和故障】检查顺序决定优先记录什么。 */
    else if (sample.radar_valid != 1) {
        result.fault_code = FAULT_SENSOR;
    }
    else if (sample.driver_enable != 1) {
        result.fault_code = FAULT_DISABLED;
    }
    else if (sample.fault_present != 0) {
        result.fault_code = FAULT_DEVICE;
    }

    /* 【5 无效路径】故障码!=0时，保持valid=0且warning=0。 */
    if (result.fault_code != FAULT_NONE) {
        if (VehicleIf_Write(&result) != 0) return -4;
        return -3;
    }

    /* 【6 正常路径】35m仅为教学阈值；不控制真实车辆执行器。 */
    result.warning = sample.distance_m <= 35.0f ? 1 : 0;
    result.valid = 1;
    result.fault_code = FAULT_NONE;

    /* 【7 写输出】Write成功才认为这一帧发布；失败时返回-4。 */
    if (VehicleIf_Write(&result) != 0) return -4;
    return 0;
}

#ifndef MOCK_H
#define MOCK_H
