#include "monitor.h" /* Monitor_Init与Monitor_Step声明。 */
#include "mock.h"    /* 预设场景输入和场景数量。 */
#include <stdio.h>   /* scanf和printf。 */

int main(void)
{
    int scenario = 0; /* 用户输入0～8，代表一次完整7帧测试。 */
    if (scanf("%d", &scenario) != 1 || scenario < 0 ||
        scenario >= SCENARIO_COUNT) {
        printf("input_error=1\n");
        return 1;
    }

    MonitorContext ctx;   /* 同一个ctx必须保留七次调用后的状态。 */
    Monitor_Init(&ctx);   /* 初始化发生在for循环之前，只有一次。 */
    printf("scenario=%d frames=%d\n", scenario, FRAME_COUNT);

    for (int i = 0; i < FRAME_COUNT; ++i) {
        MonitorInput input = {0}; /* 每一帧新建输入对象。 */
        if (Mock_GetFrame(scenario, i, &input) != 0) return 2;
        /* main→Mock_GetFrame→Monitor_Step→main，真实执行顺序。 */
        MonitorResult result = Monitor_Step(&ctx, &input);
        printf("frame=%d now=%u speed=%.1f distance=%.1f dt=%u "
               "status=%d state=%d valid=%d alert=%d age=%u\n",
               i, (unsigned)input.now_ms, (double)input.speed_mps,
               (double)input.distance_m, (unsigned)result.dt_ms,
               result.status, (int)result.state, result.valid, result.alert,
               (unsigned)result.age_ms);
    }
    return 0;
}
